export type ApiProblem = { status: number; message: string; requestId?: string; network?: boolean }
export type WorkspaceSession = { workspaceId: string; userId: string; userName?: string }

const baseUrl = (import.meta.env.VITE_API_BASE_URL ?? '').replace(/\/$/, '')

export class ApiClientError extends Error {
  problem: ApiProblem
  constructor(problem: ApiProblem) { super(problem.message); this.problem = problem }
}

function headers(session?: WorkspaceSession, extra: HeadersInit = {}) {
  const output = new Headers(extra)
  output.set('accept', 'application/json')
  if (session) { output.set('x-user-id', session.userId); output.set('x-workspace-id', session.workspaceId) }
  return output
}

export async function request<T>(path: string, options: RequestInit & { session?: WorkspaceSession } = {}): Promise<T> {
  const controller = options.signal ? null : new AbortController()
  try {
    const response = await fetch(baseUrl + path, { ...options, headers: headers(options.session, options.headers), signal: options.signal ?? controller?.signal })
    const payload = await response.json().catch(() => ({})) as { error?: string; requestId?: string } & T
    if (!response.ok) throw new ApiClientError({ status: response.status, message: payload.error ?? ('请求失败（' + response.status + '）'), requestId: payload.requestId })
    return payload as T
  } catch (error) {
    if (error instanceof ApiClientError || error instanceof DOMException) throw error
    throw new ApiClientError({ status: 0, network: true, message: '无法连接本地 API。请确认 8787 服务正在运行。' })
  } finally { controller?.abort() }
}

