export function getDashboard(session: WorkspaceSession, marketPackId: string, params: { assessmentRunId?: string; baselineRunId?: string } = {}) {
  const search = new URLSearchParams(); if (params.assessmentRunId) search.set('assessmentRunId', params.assessmentRunId); if (params.baselineRunId) search.set('baselineRunId', params.baselineRunId)
  return request<{ dashboard: Dashboard }>('/api/workspaces/' + session.workspaceId + '/market-packs/' + marketPackId + '/dashboard' + (search.size ? '?' + search : ''), { session })
}
