export function listResources(session: WorkspaceSession) { return Promise.all([
  request<{ datasets: Dataset[] }>('/api/workspaces/' + session.workspaceId + '/datasets', { session }),
  request<{ briefs: ContentBrief[] }>('/api/workspaces/' + session.workspaceId + '/content-briefs', { session }),
  request<{ drafts: ContentDraft[] }>('/api/workspaces/' + session.workspaceId + '/content-drafts', { session }),
  request<{ tasks: DistributionTask[] }>('/api/workspaces/' + session.workspaceId + '/distribution-tasks', { session }),
  request<{ reports: Report[] }>('/api/workspaces/' + session.workspaceId + '/reports', { session }),
])
}

