export function listCompetitorLinkCandidates(session: WorkspaceSession, scope: { queryGroupId?: string; observationId?: string } = {}) {
  const params = new URLSearchParams()
  if (scope.queryGroupId) params.set('queryGroupId', scope.queryGroupId)
  if (scope.observationId) params.set('observationId', scope.observationId)
  const suffix = params.size ? `?${params.toString()}` : ''
  return request<{ candidates: CompetitorLinkCandidate[] }>(`/api/workspaces/${session.workspaceId}/competitor-intelligence/link-candidates${suffix}`, { session })
}
