export type QueryResearchMetadata = { queryType?: string; journeyStage?: string; targetEntityType?: string; targetEntities?: string[]; audienceSegment?: string; scenario?: string; sourceType?: string; sourceReference?: string; queryGroup?: string; isBaseline?: boolean }
