export type RealSurfaceObservation = { id: string; rawAnswer: string; citations: string[]; answerUrl?: string | null; captureReference?: string | null; freshSession: boolean; searchEnabled: boolean; platformLabel: string; platformVersion?: string | null; observedAt: string; submittedBy: string; submittedAt: string; reviewedBy?: string | null; reviewedAt?: string | null; reviewerNote?: string | null; collectionMethod?: 'controlled-manual'|'browser-agent'; browserAgentId?: string | null; adapterId?: string | null; adapterVersion?: string | null; evidenceHash?: string | null; captureMetadata?: Record<string, unknown> | null }
